```ts
import {
  CookieTransactionStore,
  ServerClient,
  StatelessPoppyGuestStore,
  StatelessStateStore,
} from '@auth0/auth0-server-js';

const auth0 = new ServerClient<StoreOptions>({
  domain: '<AUTH0_DOMAIN>',
  clientId: '<AUTH0_CLIENT_ID>',
  clientSecret: '<AUTH0_CLIENT_SECRET>',
  // For a signed-in join, `audience` has to be the API of the agent's token (see "The audience of your login route" in EXAMPLES.md).
  authorizationParams: { redirect_uri: '<AUTH0_REDIRECT_URI>', audience: '<API_IDENTIFIER>' },
  transactionStore: new CookieTransactionStore({ secret }, new FastifyCookieHandler()),
  stateStore: new StatelessStateStore({ secret }, new FastifyCookieHandler()),
  poppy: {
    config: poppyConfig, // the parsed poppy.json that `auth0 poppy config` writes, passed as it is
    guestStore: new StatelessPoppyGuestStore({ secret }, new FastifyCookieHandler()),
  },
});

// On a request: does a person or an agent's browser make it?
const context = await auth0.poppy.getContext(storeOptions);

if (context.kind === 'agent') {
  // `state` is 'guest' for a guest and 'signed_in' for a signed-in agent.
  // `act` is the act claim of the ID token as Auth0 sent it: `act.sub` is the agent. `key` names the Session.
  console.log(context.state, context.act.sub, context.key);
}
```
